#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

use std::fs;
use std::process::Command;
use std::sync::Mutex;
use serde::Serialize;
use sysinfo::{Disks, System};
use tauri::State;

#[cfg(target_os = "windows")]
use std::os::windows::process::CommandExt;

#[cfg(target_os = "windows")]
const CREATE_NO_WINDOW: u32 = 0x08000000;

struct SysState(Mutex<System>);

#[derive(Serialize)]
struct DiskInfo {
    name: String,
    used_gb: f64,
    total_gb: f64,
    percent: f64,
    is_ssd: bool,
}

#[derive(Serialize)]
struct SystemStats {
    cpu_percent: f64,
    ram_used_gb: f64,
    ram_total_gb: f64,
    ram_percent: f64,
    gpu_percent: Option<f64>,
    disks: Vec<DiskInfo>,
}

/// Lê o uso real de CPU e RAM via sysinfo (biblioteca nativa, sem depender
/// de comandos externos — bem rápido, roda em memória). A checagem de GPU
/// é opcional (include_gpu) porque ela precisa abrir um processo do
/// PowerShell nos bastidores e é bem mais lenta — por isso só é chamada
/// de vez em quando pelo frontend, nunca a cada atualização.
#[tauri::command]
async fn get_system_stats(state: State<'_, SysState>, include_gpu: bool) -> Result<SystemStats, String> {
    let (cpu_percent, ram_used_gb, ram_total_gb, ram_percent) = {
        let mut sys = state.0.lock().unwrap();
        sys.refresh_cpu_usage();
        sys.refresh_memory();

        let cpu = sys.global_cpu_usage() as f64;
        let total = sys.total_memory() as f64 / 1_073_741_824.0;
        let used = sys.used_memory() as f64 / 1_073_741_824.0;
        let percent = if total > 0.0 { (used / total) * 100.0 } else { 0.0 };
        (cpu, used, total, percent)
    };

    let disks_list = Disks::new_with_refreshed_list();
    let disks: Vec<DiskInfo> = disks_list
        .iter()
        .map(|d| {
            let total = d.total_space() as f64 / 1_073_741_824.0;
            let avail = d.available_space() as f64 / 1_073_741_824.0;
            let used = (total - avail).max(0.0);
            let percent = if total > 0.0 { (used / total) * 100.0 } else { 0.0 };
            DiskInfo {
                name: d.mount_point().to_string_lossy().to_string(),
                used_gb: (used * 10.0).round() / 10.0,
                total_gb: (total * 10.0).round() / 10.0,
                percent: (percent * 10.0).round() / 10.0,
                is_ssd: d.is_removable() == false && matches!(d.kind(), sysinfo::DiskKind::SSD),
            }
        })
        .collect();

    // GPU: sysinfo não lê uso de GPU. Usamos o contador nativo de performance
    // do Windows (GPU Engine), que funciona pra qualquer fabricante (NVIDIA/AMD/Intel)
    // sem precisar instalar nada extra — mas roda numa thread separada (spawn_blocking)
    // pra nunca travar a interface, e só quando o frontend realmente pede.
    let gpu_percent = if include_gpu {
        tauri::async_runtime::spawn_blocking(read_gpu_usage_windows)
            .await
            .unwrap_or(0.0)
    } else {
        return Ok(SystemStats {
            cpu_percent: (cpu_percent * 10.0).round() / 10.0,
            ram_used_gb: (ram_used_gb * 10.0).round() / 10.0,
            ram_total_gb: (ram_total_gb * 10.0).round() / 10.0,
            ram_percent: (ram_percent * 10.0).round() / 10.0,
            gpu_percent: None,
            disks,
        });
    };

    Ok(SystemStats {
        cpu_percent: (cpu_percent * 10.0).round() / 10.0,
        ram_used_gb: (ram_used_gb * 10.0).round() / 10.0,
        ram_total_gb: (ram_total_gb * 10.0).round() / 10.0,
        ram_percent: (ram_percent * 10.0).round() / 10.0,
        gpu_percent: Some(gpu_percent),
        disks,
    })
}

#[cfg(target_os = "windows")]
fn read_gpu_usage_windows() -> f64 {
    // Soma a utilização de todos os "engines" do tipo 3D de todas as GPUs —
    // é o mesmo contador que o Gerenciador de Tarefas do Windows usa.
    let ps_cmd = "(Get-Counter '\\GPU Engine(*engtype_3D)\\Utilization Percentage' -ErrorAction SilentlyContinue).CounterSamples | Measure-Object -Property CookedValue -Sum | Select-Object -ExpandProperty Sum";

    let output = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", ps_cmd])
        .creation_flags(CREATE_NO_WINDOW)
        .output();

    match output {
        Ok(o) => {
            let text = String::from_utf8_lossy(&o.stdout);
            let val: f64 = text.trim().replace(',', ".").parse().unwrap_or(0.0);
            val.min(100.0).max(0.0)
        }
        Err(_) => 0.0,
    }
}

#[cfg(not(target_os = "windows"))]
fn read_gpu_usage_windows() -> f64 {
    0.0
}

/// Recebe o texto do .bat gerado pelo painel, salva num arquivo temporário
/// e executa TOTALMENTE ESCONDIDO (sem console piscando, sem downloads).
/// O único aviso que aparece pro usuário é o próprio UAC do Windows pedindo
/// permissão de administrador — isso o sistema operacional exige e não dá
/// pra pular, mas fora isso roda tudo em segundo plano dentro do app.
#[tauri::command]
fn run_bat_script(script_text: String) -> Result<String, String> {
    let temp_dir = std::env::temp_dir();
    let file_name = format!("dgeras-run-{}.bat", uuid_like());
    let file_path = temp_dir.join(&file_name);

    fs::write(&file_path, script_text).map_err(|e| format!("Falha ao gravar script: {e}"))?;

    let path_str = file_path.to_string_lossy().to_string();

    // Usa o PowerShell só como "lançador" elevado: Start-Process com -Verb RunAs
    // dispara o UAC, e -WindowStyle Hidden garante que nenhuma janela de console
    // apareça enquanto o .bat roda por trás. -Wait espera o script terminar.
    let ps_launcher = format!(
        "Start-Process -FilePath 'cmd.exe' -ArgumentList '/c \"{path}\"' -Verb RunAs -WindowStyle Hidden -Wait",
        path = path_str.replace('\'', "''")
    );

    #[cfg(target_os = "windows")]
    let result = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", &ps_launcher])
        .creation_flags(CREATE_NO_WINDOW)
        .spawn();

    #[cfg(not(target_os = "windows"))]
    let result = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", &ps_launcher])
        .spawn();

    match result {
        Ok(_) => Ok("Ajustes aplicados com sucesso".to_string()),
        Err(e) => Err(format!("Falha ao executar script: {e}")),
    }
}

fn uuid_like() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    format!("{nanos:x}")
}

// ===== Limpeza de RAM (mesma técnica do ISLC / RAMMap) =====
//
// O Windows guarda na "Standby List" partes de memória que já foram usadas
// mas não estão mais ativas — ele mantém isso em cache achando que você pode
// precisar de novo, só que às vezes isso deixa a RAM "presa" sem uso real.
// A limpeza chama a mesma função interna do Windows (NtSetSystemInformation)
// que o Gerenciador de Tarefas e ferramentas como RAMMap usam.
//
// Isso PRECISA de admin. Pra não pedir senha toda hora (o objetivo é rodar
// sozinho a cada 3 minutos), a gente cria uma Tarefa Agendada do Windows UMA
// VEZ (pede UAC só nessa primeira vez), configurada como "privilégios mais
// altos". Depois disso, o app só manda essa tarefa "rodar agora"
// (schtasks /run), o que não pede senha de novo — o Windows já confia na
// tarefa desde que ela foi criada com privilégio elevado.

const RAM_CLEAN_TASK_NAME: &str = "FluxTweakersRamClean";

fn ram_clean_ps1_content() -> &'static str {
    r#"
$sig = @"
using System;
using System.Runtime.InteropServices;
public class FluxRam {
    [DllImport("ntdll.dll")]
    public static extern int NtSetSystemInformation(int InfoClass, IntPtr Info, int Length);

    [DllImport("advapi32.dll", SetLastError = true)]
    public static extern bool OpenProcessToken(IntPtr ProcessHandle, uint DesiredAccess, out IntPtr TokenHandle);

    [DllImport("advapi32.dll", SetLastError = true)]
    public static extern bool LookupPrivilegeValue(string lpSystemName, string lpName, out long lpLuid);

    [StructLayout(LayoutKind.Sequential)]
    public struct LUID_AND_ATTRIBUTES { public long Luid; public uint Attributes; }

    [StructLayout(LayoutKind.Sequential)]
    public struct TOKEN_PRIVILEGES { public uint PrivilegeCount; public LUID_AND_ATTRIBUTES Privileges; }

    [DllImport("advapi32.dll", SetLastError = true)]
    public static extern bool AdjustTokenPrivileges(IntPtr TokenHandle, bool DisableAllPrivileges,
        ref TOKEN_PRIVILEGES NewState, uint BufferLength, IntPtr PreviousState, IntPtr ReturnLength);

    [DllImport("kernel32.dll")]
    public static extern IntPtr GetCurrentProcess();
}
"@
Add-Type -TypeDefinition $sig -ErrorAction SilentlyContinue

$before = (Get-Counter '\Memory\Available MBytes').CounterSamples[0].CookedValue

# Habilita o privilégio SeProfileSingleProcessPrivilege no processo atual —
# sem isso o Windows recusa a limpeza sem avisar nada.
$TOKEN_ADJUST_PRIVILEGES = 0x20
$TOKEN_QUERY = 0x8
$hToken = [IntPtr]::Zero
[FluxRam]::OpenProcessToken([FluxRam]::GetCurrentProcess(), ($TOKEN_ADJUST_PRIVILEGES -bor $TOKEN_QUERY), [ref]$hToken) | Out-Null

$luid = 0
[FluxRam]::LookupPrivilegeValue($null, "SeProfileSingleProcessPrivilege", [ref]$luid) | Out-Null

$priv = New-Object FluxRam+TOKEN_PRIVILEGES
$priv.PrivilegeCount = 1
$priv.Privileges = New-Object FluxRam+LUID_AND_ATTRIBUTES
$priv.Privileges.Luid = $luid
$priv.Privileges.Attributes = 0x2  # SE_PRIVILEGE_ENABLED

[FluxRam]::AdjustTokenPrivileges($hToken, $false, [ref]$priv, 0, [IntPtr]::Zero, [IntPtr]::Zero) | Out-Null

# Agora sim, purga a Standby List (mesma chamada que RAMMap/ISLC usam)
$SystemMemoryListInformation = 80
$MemoryPurgeStandbyList = 4
$ptr = [System.Runtime.InteropServices.Marshal]::AllocHGlobal(4)
[System.Runtime.InteropServices.Marshal]::WriteInt32($ptr, $MemoryPurgeStandbyList)
$status = [FluxRam]::NtSetSystemInformation($SystemMemoryListInformation, $ptr, 4)
[System.Runtime.InteropServices.Marshal]::FreeHGlobal($ptr)

Start-Sleep -Milliseconds 400
$after = (Get-Counter '\Memory\Available MBytes').CounterSamples[0].CookedValue
$freed = [math]::Round($after - $before, 0)

$resultDir = "$env:TEMP\FluxTweakers"
New-Item -ItemType Directory -Force -Path $resultDir | Out-Null
if ($status -eq 0) {
    "OK|$freed" | Out-File -FilePath "$resultDir\ram_clean_result.txt" -Encoding utf8
} else {
    "ERRO|status=$status" | Out-File -FilePath "$resultDir\ram_clean_result.txt" -Encoding utf8
}
"#
}

/// Prepara tudo pra limpeza automática funcionar: grava o script de limpeza
/// num local fixo e registra a Tarefa Agendada elevada. Só precisa rodar
/// uma vez (pede UAC essa única vez); chamadas seguintes são silenciosas.
#[tauri::command]
fn setup_ram_cleaner() -> Result<String, String> {
    let dir = std::env::temp_dir().join("FluxTweakers");
    fs::create_dir_all(&dir).map_err(|e| format!("Falha ao criar pasta: {e}"))?;
    let ps1_path = dir.join("ram_clean.ps1");
    fs::write(&ps1_path, ram_clean_ps1_content())
        .map_err(|e| format!("Falha ao gravar script de limpeza: {e}"))?;

    let ps1_str = ps1_path.to_string_lossy().to_string();

    // Cria (ou substitui) a tarefa agendada, rodando como o usuário atual
    // com privilégios mais altos. O /SC ONCE /ST 00:00 é só um gatilho
    // "dummy" — na prática a gente sempre dispara manualmente via /run.
    let create_cmd = format!(
        "schtasks /Create /TN \"{name}\" /TR \"powershell -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File \\\"{script}\\\"\" /SC ONCE /ST 00:00 /RL HIGHEST /F",
        name = RAM_CLEAN_TASK_NAME,
        script = ps1_str
    );

    let ps_launcher = format!(
        "Start-Process -FilePath 'cmd.exe' -ArgumentList '/c {cmd}' -Verb RunAs -WindowStyle Hidden -Wait",
        cmd = create_cmd.replace('\'', "''")
    );

    #[cfg(target_os = "windows")]
    let result = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", &ps_launcher])
        .creation_flags(CREATE_NO_WINDOW)
        .spawn()
        .and_then(|mut c| c.wait());

    #[cfg(not(target_os = "windows"))]
    let result: std::io::Result<std::process::ExitStatus> = Command::new("powershell")
        .args(["-NoProfile", "-WindowStyle", "Hidden", "-Command", &ps_launcher])
        .spawn()
        .and_then(|mut c| c.wait());

    match result {
        Ok(_) => Ok("Limpeza automática de RAM configurada".to_string()),
        Err(e) => Err(format!("Falha ao configurar: {e}")),
    }
}

/// Dispara a limpeza (roda a tarefa agendada já configurada). Não pede UAC
/// de novo — a tarefa já "nasceu" elevada. Espera um pouco e lê o resultado
/// real gravado pelo script (sucesso + quanto de RAM foi liberado, ou erro).
#[tauri::command]
async fn run_ram_clean() -> Result<String, String> {
    let result_path = std::env::temp_dir().join("FluxTweakers").join("ram_clean_result.txt");
    let _ = fs::remove_file(&result_path); // limpa resultado antigo antes de rodar de novo

    #[cfg(target_os = "windows")]
    let spawn_result = Command::new("schtasks")
        .args(["/Run", "/TN", RAM_CLEAN_TASK_NAME])
        .creation_flags(CREATE_NO_WINDOW)
        .output();

    #[cfg(not(target_os = "windows"))]
    let spawn_result = Command::new("schtasks")
        .args(["/Run", "/TN", RAM_CLEAN_TASK_NAME])
        .output();

    match spawn_result {
        Ok(o) if !o.status.success() => {
            return Err(format!(
                "Tarefa não encontrada — ative o interruptor de novo para reconfigurar. ({})",
                String::from_utf8_lossy(&o.stderr).trim()
            ));
        }
        Err(e) => return Err(format!("Falha ao rodar limpeza: {e}")),
        _ => {}
    }

    // Espera até 6 segundos pelo resultado (o script leva menos de 1s normalmente,
    // mas dá uma folga pra máquinas mais lentas ou o Agendador demorar a iniciar).
    for _ in 0..30 {
        tokio::time::sleep(std::time::Duration::from_millis(200)).await;
        if let Ok(content) = fs::read_to_string(&result_path) {
            let content = content.trim();
            if let Some(freed) = content.strip_prefix("OK|") {
                let freed_mb: i64 = freed.parse().unwrap_or(0);
                return Ok(if freed_mb > 0 {
                    format!("RAM limpa — cerca de {freed_mb} MB liberados")
                } else {
                    "RAM limpa (cache já estava baixo, pouco a liberar)".to_string()
                });
            } else if let Some(err) = content.strip_prefix("ERRO|") {
                return Err(format!("O Windows recusou a limpeza ({err})"));
            }
        }
    }

    Err("A limpeza não respondeu a tempo — tente de novo".to_string())
}

fn main() {
    tauri::Builder::default()
        .plugin(tauri_plugin_updater::Builder::new().build())
        .plugin(tauri_plugin_process::init())
        .manage(SysState(Mutex::new(System::new_all())))
        .invoke_handler(tauri::generate_handler![run_bat_script, get_system_stats, setup_ram_cleaner, run_ram_clean])
        .run(tauri::generate_context!())
        .expect("erro ao rodar o app By Dgeras");
}


